def page(items, cursor=None, limit=2):
    if limit < 1: raise ValueError('limit')
    rows = sorted(items, key=lambda row: row['id'])
    if cursor is not None: rows = [r for r in rows if r['id'] >= cursor]
    selected = rows[:limit]
    return {'items': selected, 'next_cursor': selected[-1]['id'] if selected else None}

argv:
from api import page; assert [r['id'] for r in page([{'id':4},{'id':1}])['items']]==[1,4];
try: page([],limit=0)
except ValueError: pass
else: raise AssertionError('validation')

files.messages.py:
def send(store, key, body):
    message = {'id': len(store)+1, 'key': key, 'body': body}
    store[key] = message
    return message

argv:
from messages import send; s={}; a=send(s,'k','hello'); b=send(s,'k','hello'); assert a==b and len(s)==1;
try: send(s,'k','changed')
except ValueError: pass
else: raise AssertionError('conflict')
assert s['k']==a

files.filters.py:
def reduce(state, event):
    if event['type']=='filter':
        return {'filters': {event['key']:event['value']}, 'page':state['page'], 'sort':'name'}
    if event['type']=='clear': return {'filters':{},'page':1,'sort':'name'}
    return {**state, 'page':event['value']}

files.migrate.py:
def apply(conn, statements):
    for sql in statements:
        conn.execute(sql)
        conn.commit()

argv:
import sqlite3; from migrate import apply; c=sqlite3.connect(':memory:'); c.execute('CREATE TABLE items(id INTEGER PRIMARY KEY)'); c.execute('INSERT INTO items VALUES(1)'); c.commit();
try: apply(c,['INSERT INTO items VALUES(2)','INSERT INTO missing VALUES(3)'])
except sqlite3.Error: pass
else: raise AssertionError('failure was hidden')
assert c.execute('SELECT id FROM items ORDER BY id').fetchall()==[(1,)]

